"""Write the eval report from a fresh replay. Figures are [Measured] on this run."""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from evals.harness import replay_all, summarize


def main() -> None:
    v2 = summarize(replay_all("v2"))
    v1 = summarize(replay_all("v1"))
    misses = v1["misses"]
    caused = [miss for miss in misses if miss.get("cause")]
    shown = (caused or misses)[:10]
    lines = [
        "# Eval report",
        "",
        "Generated by `python scripts/write_report.py`. Figures in this file are [Measured] on the offline instruction packs unless marked otherwise. They are not a production traffic result.",
        "",
        "## Gate",
        "",
        f"- Compliance violations: {len(v2['violations'])} [Measured]",
        f"- Must-escalate recall: {v2['escalation_hit']}/{v2['escalation_n']} = {v2['escalation_recall']:.1%} [Measured]. Target 98%.",
        f"- Intent accuracy, pack v2: {v2['intent_hit']}/{v2['intent_n']} = {v2['intent_accuracy']:.1%} [Measured]. Target 85%.",
        f"- Intent accuracy, keyword pack v1: {v1['intent_hit']}/{v1['intent_n']} = {v1['intent_accuracy']:.1%} [Measured].",
        f"- Lift over keyword baseline: {(v2['intent_accuracy'] - v1['intent_accuracy']) * 100:.1f} points [Measured]. Target 10.",
        f"- Promised date and amount: {v2['slot_hit']}/{v2['slot_n']} = {v2['slot_accuracy']:.1%} [Measured]. Target 90%.",
        f"- Reply latency p95, local pack: {v2['p95_ms']:.1f} ms across {v2['n_turns']} turns [Measured]. Target 2500 ms.",
        "- Hosted-model latency: not run. [Projected] until `MODEL_BACKEND=litellm` is pointed at a key.",
        "",
        "Pack v1 is wrapped by the same policy as v2. A weak classifier still cannot disclose a balance or confirm a below-floor plan. That is why v1 can miss intent and still produce zero borrower-facing violations.",
        "",
        "## Ten failures and their causes",
        "",
        "These are misses of the keyword pack on the same 80 conversations. They are the failures a first prompt would ship. Pack v2 plus the policy gate is what `make gate` grades.",
        "",
    ]
    if len(shown) < 10:
        lines.append(f"Only {len(shown)} actual v1 misses were measured. The list is not padded.")
        lines.append("")
    for index, miss in enumerate(shown, start=1):
        lines.append(f"### {index}. `{miss['id']}`")
        lines.append("")
        lines.append(f"- Borrower: {miss['text']}")
        lines.append(f"- Gold intent: `{miss['gold']}`. Keyword pack returned `{miss['got']}`.")
        lines.append(f"- Cause: {miss.get('cause') or 'Measured miss. No analyst note was stored on this case.'}")
        lines.append("")
    lines.extend(
        [
            "## What this does not prove",
            "",
            "- [Projected] Containment on a real 1–30 book. The 70% in the ROI note is an input, not this run.",
            "- [Projected] Hosted-model latency and intent. The packs are deterministic stand-ins so the gate can fail a build without a network call.",
            "- [Synthetic] The 200 accounts. UCI supplied the delinquency shape where the file downloaded. Names, PAN last-4, and rupee amounts are not borrower data.",
            "",
        ]
    )
    target = ROOT / "docs" / "eval_report.md"
    target.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {target}")
    print(
        f"v2 intent {v2['intent_accuracy']:.1%} v1 {v1['intent_accuracy']:.1%} "
        f"esc {v2['escalation_recall']:.1%} slots {v2['slot_accuracy']:.1%} "
        f"violations {len(v2['violations'])} p95 {v2['p95_ms']:.1f}ms"
    )


if __name__ == "__main__":
    main()
